// === Tab: mySketch ===

var num = 1000;
var vx = new Array(num);
var vy = new Array(num);
var x = new Array(num);
var y = new Array(num);
var ax = new Array(num);
var ay = new Array(num);

var magnetism = 10.0; //吸引力的力量。。
var radius = 1 ; //画圆的半径
var gensoku = 0.95; // 减慢粒子运动

function setup(){
  createCanvas(1943,425);
  noStroke(); 
  fill(0);
  ellipseMode(RADIUS);
  background(0);
  blendMode(ADD);

  for(var i =0; i< num; i++){
    x[i] = random(width);
    y[i] = random(height);
    vx[i] = 0;
    vy[i] = 0;
    ax[i] = 0;
    ay[i] = 0;
  }
}


function draw(){
  fill(0,0,0);
  rect(0,0,width,height);

  for(var i=0; i<num; i++){
    var distance = dist(touchX, touchY, x[i], y[i]); //dist(x1,y1,x2,y2) 计算两点之间距离的函数
   //加速度与距吸引力中心的距离的平方成反比。
    if(distance > 3){ //如果距离鼠标太近则不要更新加速度
      ax[i] = magnetism * (touchX - x[i]) / (distance * distance); 
      ay[i] = magnetism * (touchY - y[i]) / (distance * distance);
    }
    vx[i] += ax[i]; // 每帧将速度vx增加ax。
    vy[i] += ay[i]; // 每帧通过ay增加速度vy。

    vx[i] = vx[i]*gensoku;
    vy[i] = vy[i]*gensoku;

    x[i] += vx[i];  // 每帧前进vy像素。
    y[i] += vy[i];  // 每帧前进vy像素。

    var sokudo = dist(0,0,vx[i],vy[i]); // 从速度的X和Y分量中查找速度
    var r = map(sokudo, 0, 5, 0, 255); //根据速度计算颜色
    var g = map(sokudo, 0,5, 64, 255);
    var b = map(sokudo, 0,5, 128, 255);
    fill(r, g, b, 32);
    ellipse(x[i],y[i],radius,radius);
  }

}

